// Lightweight wrapper so VitePWA has an entry at public/sw.js during build.
// It forwards to the injected service worker generated by the plugin.

/* eslint-disable no-undef */
// Use importScripts to load the built sw.js at runtime. Keep this file free of ESM
// imports so Rollup doesn't attempt to resolve `/sw.js` at build time.
try {
  importScripts('/sw.js');
} catch (e) {
  // If importScripts isn't available (shouldn't be in a service worker), ignore.
}
